{
  "candidate_rtl": "module mul_subexpression(
    input [7:0] multiplicand,
    input [7:0] multiplier,
    output [15:0] product
);

wire [7:0] pp [7:0];
genvar i, j;
generate
  for (i = 0; i < 8; i = i + 1) begin : gen_pp_row
    for (j = 0; j < 8; j = j + 1) begin : gen_pp_col
      assign pp[i][j] = multiplicand[i] & multiplier[j];
    end
  end
endgenerate

wire [15:0] term [7:0];
genvar t;
generate
  for (t = 0; t < 8; t = t + 1) begin : gen_term
    assign term[t] = {8'b0, pp[t]} << t;
  end
endgenerate

// Stage 1: reduce 8 rows to 6
wire [15:0] sA, cA, sB, cB;
csa3_16 csa_A (.a(term[0]), .b(term[1]), .c(term[2]), .sum(sA), .carry(cA));
csa3_16 csa_B (.a(term[3]), .b(term[4]), .c(term[5]), .sum(sB), .carry(cB));
wire [15:0] cA_sh = {cA[14:0], 1'b0};
wire [15:0] cB_sh = {cB[14:0], 1'b0};

// Stage 2: reduce 6 rows to 4
wire [15:0] sAB, cAB, sC, cC;
csa3_16 csa_AB (.a(sA), .b(cA_sh), .c(sB), .sum(sAB), .carry(cAB));
csa3_16 csa_C  (.a(cB_sh), .b(term[6]), .c(term[7]), .sum(sC), .carry(cC));
wire [15:0] cAB_sh = {cAB[14:0], 1'b0};
wire [15:0] cC_sh  = {cC[14:0], 1'b0};

// Stage 3: reduce 4 rows to 3
wire [15:0] sABC, cABC;
csa3_16 csa_ABC (.a(sAB), .b(cAB_sh), .c(sC), .sum(sABC), .carry(cABC));
wire [15:0] cABC_sh = {cABC[14:0], 1'b0};

// Stage 4: reduce 3 rows to 2
wire [15:0] sFinal, cFinal;
csa3_16 csa_Final (.a(sABC), .b(cABC_sh), .c(cC_sh), .sum(sFinal), .carry(cFinal));
wire [15:0] cFinal_sh = {cFinal[14:0], 1'b0};

// Final carry-propagate adder
assign product = sFinal + cFinal_sh;

endmodule

module csa3_16(
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    output [15:0] sum,
    output [15:0] carry
);
genvar k;
generate
  for (k = 0; k < 16; k = k + 1) begin : csa_bit
    assign sum[k]   = a[k] ^ b[k] ^ c[k];
    assign carry[k] = (a[k] & b[k]) | (a[k] & c[k]) | (b[k] & c[k]);
  end
endgenerate
endmodule",
  "bottleneck": "The original RTL accumulates shifted partial products serially: sum[i] = sum[i-1] + shifted_partial. This creates a dependency chain of seven 16-bit carry-propagate additions. In the mapped netlist the critical path is dominated by that chain of wide adders.",
  "rewrite": "Replace the serial accumulation with a Wallace-tree reduction using 3:2 carry-save adders (CSAs). The eight shifted partial-product rows are reduced through four CSA stages to two rows, followed by a single final carry-propagate adder. This changes the critical path from seven CPA levels to four CSA levels plus one CPA.",
  "expected_timing_gain": "Estimated maximum data arrival reduction from about 2.78 ns to roughly 1.5-2.0 ns under the same EDA conditions (gain of ~0.8-1.3 ns). This is a hypothesis to be verified by Yosys/OpenSTA; actual results depend on ABC mapping.",
  "area_or_other_cost": "Area is expected to remain close to baseline or increase slightly. The Wallace tree uses six 16-bit 3:2 CSA blocks (96 full adders) plus one 16-bit carry-propagate adder, comparable to the original seven 16-bit adders. Should remain within the 3261.878 um^2 area cap under the given mapping conditions.",
  "functional_boundaries": "Exact module name, input/output ports, widths, unsigned full-product behavior for all 256x256 input combinations, and zero-clock combinational nature are preserved. No clocks, state, input restrictions, assumptions, or don't-cares are introduced."
}
